import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Easing,
  random,
} from '../remotionShim';
// Generate static particle data deterministically
const PARTICLES = new Array(16).fill(0).map((_, i) => {
  const angle = random(`angle-${i}`) * Math.PI * 2;
  const speed = 15 + random(`speed-${i}`) * 25;
  const size = 8 + random(`size-${i}`) * 12;
  const isSquare = random(`shape-${i}`) > 0.5;
  return { id: i, angle, speed, size, isSquare };
});



export type HeartBreakProps = Record<string, any>;

const HeartSVG: React.FC<{ color: string; style?: React.CSSProperties }> = ({
  color,
  style,
}) => (
  <svg
    viewBox="0 0 24 24"
    fill={color}
    style={{ width: "100%", height: "100%", position: "absolute", inset: 0, ...style }}
  >
    <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" />
  </svg>
);

const HeartBreak: React.FC<HeartBreakProps> = ({
  backgroundColor = "#0f0f11",
  transparentBackground = false,
  durationInSeconds = 5,
  heartColor = "#e11d48",
  particleColor = "#fb7185",
  breakTimeInSeconds = 2.0,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  const breakFrame = Math.round(fps * breakTimeInSeconds);
  const isBroken = frame >= breakFrame;
  const tBreak = Math.max(0, frame - breakFrame);

  // Intro Scale
  const introScale = spring({
    frame,
    fps,
    config: { damping: 12, mass: 0.8 },
  });

  // Beating Animation (only before it breaks)
  const beatCycle = frame % Math.round(fps * 1.5);
  const beatScale = interpolate(
    beatCycle,
    [0, 5, 10, 15, 20],
    [1, 1.15, 1, 1.15, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  const baseScale = introScale * (isBroken ? 1 : beatScale);

  // Break & Fall Physics
  // Stage 1: The Initial Crack (spring pull apart)
  const crackProg = spring({
    frame: tBreak,
    fps,
    config: { damping: 12, mass: 0.8 },
  });

  // Stage 2: Gravity Drop (accelerates downward after a tiny delay)
  const fallT = Math.max(0, tBreak - 8);
  const gravityProgress = Math.pow(fallT, 2) * 1.8;

  // Left Half Trajectory
  const leftX = interpolate(crackProg, [0, 1], [0, -60]) - fallT * 2.5;
  const leftY = interpolate(crackProg, [0, 1], [0, -30]) + gravityProgress;
  const leftRot = interpolate(crackProg, [0, 1], [0, -15]) - fallT * 1.2;

  // Right Half Trajectory (falls slightly differently for organic feel)
  const rightX = interpolate(crackProg, [0, 1], [0, 65]) + fallT * 2.0;
  const rightY = interpolate(crackProg, [0, 1], [0, 15]) + gravityProgress * 1.1;
  const rightRot = interpolate(crackProg, [0, 1], [0, 25]) + fallT * 1.5;

  // Zig-Zag Clip Paths for the broken edge down the center
  const leftClip = `polygon(-20% -20%, 50% -20%, 45% 20%, 55% 40%, 48% 60%, 52% 80%, 50% 120%, -20% 120%)`;
  const rightClip = `polygon(120% -20%, 50% -20%, 45% 20%, 55% 40%, 48% 60%, 52% 80%, 50% 120%, 120% 120%)`;

  // Particle System Logic
  const particleOpacity = interpolate(tBreak, [10, 30], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const iconSize = width * 0.45;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      <div
        style={{
          position: "absolute",
          width: iconSize,
          height: iconSize,
          left: "50%",
          top: "50%",
          marginLeft: -iconSize / 2,
          marginTop: -iconSize / 2,
          transform: `scale(${baseScale})`,
          transition: "none",
        }}
      >
        {/* Particles */}
        {isBroken &&
          PARTICLES.map((p) => {
            const dist = spring({
              frame: tBreak,
              fps,
              config: { damping: 15, mass: 0.5 },
            }) * p.speed * (iconSize * 0.015);
            
            const px = Math.cos(p.angle) * dist;
            const py = Math.sin(p.angle) * dist + (Math.pow(fallT, 2) * 0.5);

            return (
              <div
                key={p.id}
                style={{
                  position: "absolute",
                  left: "50%",
                  top: "50%",
                  width: p.size,
                  height: p.size,
                  marginLeft: -p.size / 2,
                  marginTop: -p.size / 2,
                  backgroundColor: particleColor,
                  borderRadius: p.isSquare ? "2px" : "50%",
                  opacity: particleOpacity,
                  transform: `translate(${px}px, ${py}px) rotate(${tBreak * 5}deg)`,
                  transition: "none",
                }}
              />
            );
          })}

        {/* Left Half */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            transform: `translate(${leftX}px, ${leftY}px) rotate(${leftRot}deg)`,
            transformOrigin: "center center",
            transition: "none",
            filter: `drop-shadow(0px 10px 20px rgba(0,0,0,0.3))`,
          }}
        >
          <HeartSVG
            color={heartColor}
            style={{ clipPath: leftClip, transition: "none" }}
          />
        </div>

        {/* Right Half */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            transform: `translate(${rightX}px, ${rightY}px) rotate(${rightRot}deg)`,
            transformOrigin: "center center",
            transition: "none",
            filter: `drop-shadow(0px 10px 20px rgba(0,0,0,0.3))`,
          }}
        >
          <HeartSVG
            color={heartColor}
            style={{ clipPath: rightClip, transition: "none" }}
          />
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default HeartBreak;